namespace sv_12958319bba549bb91b9c86b69c81d7d.Services;

public record Product(int Id, string Name, decimal Price, string Category, double Rating, bool InStock, string ImageUrl);
public record ProductFilter(List<string>? Categories, decimal? MinPrice, decimal? MaxPrice, bool InStockOnly);
public record PagedResult<T>(List<T> Items, int TotalCount, int Page, int PageSize);

public interface IProductService
{
    Task<PagedResult<Product>> SearchAsync(ProductFilter filter, string sortBy, int page, int pageSize);
    Task<List<string>> GetCategoriesAsync();
}

@using sv_12958319bba549bb91b9c86b69c81d7d.Services

<div class="product-card" @onclick="HandleCardClick" style="border:1px solid #ddd;border-radius:8px;overflow:hidden;cursor:pointer;display:flex;flex-direction:column;">
    <div style="background:#e0e0e0;height:180px;display:flex;align-items:center;justify-content:center;color:#888;font-size:0.9rem;" role="img" aria-label="@Product.Name">
        @Product.Name
    </div>
    <div style="padding:12px;flex:1;display:flex;flex-direction:column;gap:6px;">
        <h4 style="margin:0;">@Product.Name</h4>
        <span style="font-size:1.1rem;font-weight:bold;color:#2a7d2e;">@Product.Price.ToString("C")</span>
        <span style="color:#f5a623;" aria-label="@($"Rating: {Product.Rating:F1} out of 5")">@RenderStars(Product.Rating)</span>
        @if (!Product.InStock)
        {
            <span style="display:inline-block;background:#e74c3c;color:#fff;padding:2px 8px;border-radius:4px;font-size:0.8rem;width:fit-content;">Out of Stock</span>
        }
        <button @onclick="HandleAddToCart" @onclick:stopPropagation="true"
                disabled="@(!Product.InStock)"
                style="margin-top:auto;padding:8px 12px;border:none;border-radius:4px;background:@(Product.InStock ? "#2a7d2e" : "#ccc");color:#fff;cursor:@(Product.InStock ? "pointer" : "not-allowed");">
            Add to Cart
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public Product Product { get; set; } = default!;
    [Parameter] public EventCallback<Product> OnProductSelected { get; set; }
    [Parameter] public EventCallback<Product> OnAddToCart { get; set; }

    private async Task HandleCardClick() => await OnProductSelected.InvokeAsync(Product);
    private async Task HandleAddToCart() => await OnAddToCart.InvokeAsync(Product);

    private static string RenderStars(double rating)
    {
        int full = (int)Math.Round(rating);
        return new string('★', full) + new string('☆', 5 - full);
    }
}

@using sv_12958319bba549bb91b9c86b69c81d7d.Services

<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:20px;">
    @foreach (var product in Products)
    {
        <ProductCard Product="product"
                     OnProductSelected="OnProductSelected"
                     OnAddToCart="OnAddToCart" />
    }
</div>

@code {
    [Parameter, EditorRequired] public List<Product> Products { get; set; } = [];
    [Parameter] public EventCallback<Product> OnProductSelected { get; set; }
    [Parameter] public EventCallback<Product> OnAddToCart { get; set; }
}

@using sv_12958319bba549bb91b9c86b69c81d7d.Services

<aside style="padding:16px;border-right:1px solid #ddd;">
    <h3 style="margin-top:0;">Filters</h3>

    <fieldset style="border:none;padding:0;margin:0 0 16px 0;">
        <legend style="font-weight:bold;margin-bottom:8px;">Categories</legend>
        @foreach (var category in Categories)
        {
            <label style="display:block;margin-bottom:4px;cursor:pointer;">
                <input type="checkbox"
                       checked="@_selectedCategories.Contains(category)"
                       @onchange="() => ToggleCategory(category)" />
                @category
            </label>
        }
    </fieldset>

    <div style="margin-bottom:16px;">
        <label style="font-weight:bold;display:block;margin-bottom:4px;">Min Price</label>
        <input type="number" min="0" step="0.01" @bind="_minPrice"
               style="width:100%;padding:6px;box-sizing:border-box;" />
    </div>

    <div style="margin-bottom:16px;">
        <label style="font-weight:bold;display:block;margin-bottom:4px;">Max Price</label>
        <input type="number" min="0" step="0.01" @bind="_maxPrice"
               style="width:100%;padding:6px;box-sizing:border-box;" />
    </div>

    <label style="display:block;margin-bottom:16px;cursor:pointer;">
        <input type="checkbox" @bind="_inStockOnly" />
        <strong>In Stock Only</strong>
    </label>

    <div style="display:flex;flex-direction:column;gap:8px;">
        <button @onclick="ApplyFilters"
                style="padding:10px;background:#2a7d2e;color:#fff;border:none;border-radius:4px;cursor:pointer;">
            Apply Filters
        </button>
        <button @onclick="ClearFilters"
                style="padding:10px;background:#888;color:#fff;border:none;border-radius:4px;cursor:pointer;">
            Clear Filters
        </button>
    </div>
</aside>

@code {
    [Parameter, EditorRequired] public List<string> Categories { get; set; } = [];
    [Parameter] public EventCallback<ProductFilter> OnFilterApplied { get; set; }

    private HashSet<string> _selectedCategories = [];
    private decimal? _minPrice;
    private decimal? _maxPrice;
    private bool _inStockOnly;

    private void ToggleCategory(string category)
    {
        if (!_selectedCategories.Remove(category))
            _selectedCategories.Add(category);
    }

    private async Task ApplyFilters()
    {
        var filter = new ProductFilter(
            _selectedCategories.Count > 0 ? _selectedCategories.ToList() : null,
            _minPrice,
            _maxPrice,
            _inStockOnly);
        await OnFilterApplied.InvokeAsync(filter);
    }

    private async Task ClearFilters()
    {
        _selectedCategories.Clear();
        _minPrice = null;
        _maxPrice = null;
        _inStockOnly = false;
        await OnFilterApplied.InvokeAsync(new ProductFilter(null, null, null, false));
    }
}

@page "/catalog"
@using sv_12958319bba549bb91b9c86b69c81d7d.Components.Catalog
@using sv_12958319bba549bb91b9c86b69c81d7d.Services
@inject IProductService ProductService
@rendermode InteractiveServer

<PageTitle>Product Catalog</PageTitle>

<h1>Product Catalog</h1>

@if (_error is not null)
{
    <div role="alert" style="padding:16px;background:#fdecea;color:#b71c1c;border-radius:6px;margin-bottom:16px;">
        <strong>Error:</strong> @_error
        <button @onclick="LoadProducts" style="margin-left:12px;padding:4px 12px;cursor:pointer;">Retry</button>
    </div>
}

<div style="display:flex;gap:24px;align-items:flex-start;">
    <div style="flex:0 0 25%;min-width:220px;">
        <CatalogSidebar Categories="_categories" OnFilterApplied="HandleFilterApplied" />
    </div>

    <div style="flex:1;min-width:0;">
        <CatalogToolbar SortBy="@_sortBy"
                        TotalCount="_totalCount"
                        Page="_page"
                        PageSize="PageSize"
                        OnSortChanged="HandleSortChanged" />

        @if (_loading)
        {
            <div style="text-align:center;padding:48px;color:#888;">Loading products…</div>
        }
        else if (_products.Count == 0)
        {
            <div style="text-align:center;padding:48px;color:#888;">No products found. Try adjusting your filters.</div>
        }
        else
        {
            <ProductGrid Products="_products"
                         OnProductSelected="HandleProductSelected"
                         OnAddToCart="HandleAddToCart" />

            @if (_totalPages > 1)
            {
                <CatalogPagination Page="_page"
                                   TotalPages="_totalPages"
                                   OnPageChanged="HandlePageChanged" />
            }
        }
    </div>
</div>

@code {
    private const int PageSize = 12;

    private List<Product> _products = [];
    private List<string> _categories = [];
    private ProductFilter _filter = new(null, null, null, false);
    private string _sortBy = "price_asc";
    private int _page = 1;
    private int _totalCount;
    private int _totalPages;
    private bool _loading = true;
    private string? _error;

    /// <summary>Parent can handle navigation to a product detail page.</summary>
    [Parameter] public EventCallback<Product> OnProductSelected { get; set; }

    [Parameter] public EventCallback<Product> OnAddToCart { get; set; }

    protected override async Task OnInitializedAsync()
    {
        try
        {
            var categoriesTask = ProductService.GetCategoriesAsync();
            var productsTask = ProductService.SearchAsync(_filter, _sortBy, _page, PageSize);
            await Task.WhenAll(categoriesTask, productsTask);

            _categories = categoriesTask.Result;
            ApplyResult(productsTask.Result);
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task LoadProducts()
    {
        _loading = true;
        _error = null;
        try
        {
            var result = await ProductService.SearchAsync(_filter, _sortBy, _page, PageSize);
            ApplyResult(result);
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private void ApplyResult(PagedResult<Product> result)
    {
        _products = result.Items;
        _totalCount = result.TotalCount;
        _totalPages = (int)Math.Ceiling((double)result.TotalCount / PageSize);
    }

    private async Task HandleFilterApplied(ProductFilter filter)
    {
        _filter = filter;
        _page = 1;
        await LoadProducts();
    }

    private async Task HandleSortChanged(string sortBy)
    {
        _sortBy = sortBy;
        _page = 1;
        await LoadProducts();
    }

    private async Task HandlePageChanged(int page)
    {
        _page = page;
        await LoadProducts();
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private async Task HandleAddToCart(Product product)
    {
        await OnAddToCart.InvokeAsync(product);
    }
}

