{"path": "/tmp/sv-12958319bba549bb91b9c86b69c81d7d/Components/Catalog/CatalogSidebar.razor", "file_text": "@using sv_12958319bba549bb91b9c86b69c81d7d.Services

<aside style="padding:16px;border-right:1px solid #ddd;">
    <h3 style="margin-top:0;">Filters</h3>

    <fieldset style="border:none;padding:0;margin:0 0 16px 0;">
        <legend style="font-weight:bold;margin-bottom:8px;">Categories</legend>
        @foreach (var category in Categories)
        {
            <label style="display:block;margin-bottom:4px;cursor:pointer;">
                <input type="checkbox"
                       checked="@_selectedCategories.Contains(category)"
                       @onchange="() => ToggleCategory(category)" />
                @category
            </label>
        }
    </fieldset>

    <div style="margin-bottom:16px;">
        <label style="font-weight:bold;display:block;margin-bottom:4px;">Min Price</label>
        <input type="number" min="0" step="0.01" @bind="_minPrice"
               style="width:100%;padding:6px;box-sizing:border-box;" />
    </div>

    <div style="margin-bottom:16px;">
        <label style="font-weight:bold;display:block;margin-bottom:4px;">Max Price</label>
        <input type="number" min="0" step="0.01" @bind="_maxPrice"
               style="width:100%;padding:6px;box-sizing:border-box;" />
    </div>

    <label style="display:block;margin-bottom:16px;cursor:pointer;">
        <input type="checkbox" @bind="_inStockOnly" />
        <strong>In Stock Only</strong>
    </label>

    <div style="display:flex;flex-direction:column;gap:8px;">
        <button @onclick="ApplyFilters"
                style="padding:10px;background:#2a7d2e;color:#fff;border:none;border-radius:4px;cursor:pointer;">
            Apply Filters
        </button>
        <button @onclick="ClearFilters"
                style="padding:10px;background:#888;color:#fff;border:none;border-radius:4px;cursor:pointer;">
            Clear Filters
        </button>
    </div>
</aside>

@code {
    [Parameter, EditorRequired] public List<string> Categories { get; set; } = [];
    [Parameter] public EventCallback<ProductFilter> OnFilterApplied { get; set; }

    private HashSet<string> _selectedCategories = [];
    private decimal? _minPrice;
    private decimal? _maxPrice;
    private bool _inStockOnly;

    private void ToggleCategory(string category)
    {
        if (!_selectedCategories.Remove(category))
            _selectedCategories.Add(category);
    }

    private async Task ApplyFilters()
    {
        var filter = new ProductFilter(
            _selectedCategories.Count > 0 ? _selectedCategories.ToList() : null,
            _minPrice,
            _maxPrice,
            _inStockOnly);
        await OnFilterApplied.InvokeAsync(filter);
    }

    private async Task ClearFilters()
    {
        _selectedCategories.Clear();
        _minPrice = null;
        _maxPrice = null;
        _inStockOnly = false;
        await OnFilterApplied.InvokeAsync(new ProductFilter(null, null, null, false));
    }
}
"}

{"path": "/tmp/sv-12958319bba549bb91b9c86b69c81d7d/Components/Catalog/CatalogToolbar.razor", "file_text": "<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:16px;flex-wrap:wrap;gap:12px;">
    <div>
        <label for="sort-select" style="margin-right:6px;font-weight:bold;">Sort by:</label>
        <select id="sort-select" value="@SortBy" @onchange="HandleSortChanged"
                style="padding:6px 10px;border-radius:4px;border:1px solid #ccc;">
            @foreach (var option in _sortOptions)
            {
                <option value="@option.Value">@option.Label</option>
            }
        </select>
    </div>
    <span style="color:#555;">
        @if (TotalCount > 0)
        {
            var start = (Page - 1) * PageSize + 1;
            var end = Math.Min(Page * PageSize, TotalCount);
            @($"Showing {start}–{end} of {TotalCount} products")
        }
        else
        {
            @("No products to show")
        }
    </span>
</div>

@code {
    [Parameter] public string SortBy { get; set; } = "price_asc";
    [Parameter] public int TotalCount { get; set; }
    [Parameter] public int Page { get; set; } = 1;
    [Parameter] public int PageSize { get; set; } = 12;
    [Parameter] public EventCallback<string> OnSortChanged { get; set; }

    private readonly record struct SortOption(string Value, string Label);

    private static readonly SortOption[] _sortOptions =
    [
        new("price_asc", "Price: Low to High"),
        new("price_desc", "Price: High to Low"),
        new("name_asc", "Name: A-Z"),
        new("rating_desc", "Rating: Highest"),
    ];

    private async Task HandleSortChanged(ChangeEventArgs e)
    {
        await OnSortChanged.InvokeAsync(e.Value?.ToString() ?? "price_asc");
    }
}
"}

{"path": "/tmp/sv-12958319bba549bb91b9c86b69c81d7d/Components/Catalog/CatalogPagination.razor", "file_text": "<nav aria-label="Product pagination" style="display:flex;justify-content:center;align-items:center;gap:4px;margin-top:24px;flex-wrap:wrap;">
    <button disabled="@(Page <= 1)" @onclick="() => GoToPage(Page - 1)"
            style="padding:8px 14px;border:1px solid #ccc;border-radius:4px;background:#fff;cursor:@(Page <= 1 ? "not-allowed" : "pointer");">
        Previous
    </button>

    @for (int i = 1; i <= TotalPages; i++)
    {
        var pageNum = i;
        <button @onclick="() => GoToPage(pageNum)"
                style="padding:8px 12px;border:1px solid #ccc;border-radius:4px;cursor:pointer;background:@(pageNum == Page ? "#2a7d2e" : "#fff");color:@(pageNum == Page ? "#fff" : "#333");">
            @pageNum
        </button>
    }

    <button disabled="@(Page >= TotalPages)" @onclick="() => GoToPage(Page + 1)"
            style="padding:8px 14px;border:1px solid #ccc;border-radius:4px;background:#fff;cursor:@(Page >= TotalPages ? "not-allowed" : "pointer");">
        Next
    </button>
</nav>

@code {
    [Parameter] public int Page { get; set; } = 1;
    [Parameter] public int TotalPages { get; set; } = 1;
    [Parameter] public EventCallback<int> OnPageChanged { get; set; }

    private async Task GoToPage(int page) => await OnPageChanged.InvokeAsync(page);
}
"}

